data.value:
SELECT *, ROW_NUMBER() OVER (ORDER BY Cast(SAL_ContractHeader.ContractNo as int) desc) AS 'Row' FROM ( SELECT distinct soh_Outer.ContractID, soh_Outer.CompanyID, soh_Outer.PeriodID, soh_Outer.SaleContractTypeID, soh_Outer.CustomerID, soh_Outer.BrokerID, soh_Outer.PaymentTermID, soh_Outer.Season, soh_Outer.ContractNo, soh_Outer.ContractDate, soh_Outer.PaymentDate, soh_Outer.DispatchDate, soh_Outer.DTRENo, soh_Outer.DTREDate, soh_Outer.IsApproved, soh_Outer.ApprovedBy, soh_Outer.ApprovalDate, soh_Outer.Remarks, soh_Outer.IsPaid, soh_Outer.PaidAmount, soh_Outer.StatusCode, soh_Outer.Status, soh_Outer.CreatedBy, soh_Outer.CreateDate, soh_Outer.UpdatedBy, soh_Outer.UpdateDate, soh_Outer.CreatedByValue, soh_Outer.UpdatedByValue, AR_SET_Customer.CustomerName AS 'Customer', tbl_Broker.CustomerName AS 'Broker', SET_DocumentApprove.ApprovalStatus, Set_documentPendingApprove.ApprovalOperator, Set_documentPendingApprove.ApprovalUserID AS UserID, --sum(SAL_ContractDetail.Quantity) as Quantity, (select sum(Quantity) from SAL_ContractDetail Saldtl where Saldtl.ContractID = SAL_ContractDetail.ContractID and Saldtl.CompanyID = SAL_ContractDetail.CompanyID and Saldtl.PeriodID = SAL_ContractDetail.PeriodID and Saldtl.Status = 1
) as Quantity, SET_Documenttype.DocumentType ,soh_Outer.ContractDate as DocumentDate ,soh_Outer.ContractNo as DocumentNo ,SET_PeriodCustom.PeriodSetName --,UsersInRoles.UserId As R_UserID FROM SAL_ContractHeader soh_Outer INNER JOIN SAL_ContractDetail ON SAL_ContractDetail.ContractID = soh_Outer.ContractID AND SAL_ContractDetail.CompanyID = soh_Outer.CompanyID AND SAL_ContractDetail.PeriodID = soh_Outer.PeriodID AND SAL_ContractDetail.Status = 1 INNER JOIN INV_Item ON INV_Item.ItemID = SAL_ContractDetail.ItemID AND INV_Item.Status = 1 INNER JOIN AR_SET_Customer ON AR_SET_Customer.CustomerID = soh_Outer.CustomerID --AND AR_SET_Customer.CompanyID = soh_Outer.CompanyID AND AR_SET_Customer.PeriodID = soh_Outer.PeriodID AND AR_SET_Customer.Status = 1 LEFT JOIN AR_SET_Customer AS tbl_Broker ON tbl_Broker.CustomerID = soh_Outer.BrokerID --AND tbl_Broker.CompanyID = soh_Outer.CompanyID AND tbl_Broker.PeriodID = soh_Outer.PeriodID AND tbl_Broker.Status = 1 INNER JOIN SET_DocumentApprove ON SET_DocumentApprove.CompanyID = soh_Outer.CompanyID AND SET_DocumentApprove.PeriodID = soh_Outer.PeriodID AND SET_DocumentApprove.Status = 1 AND SET_DocumentApprove.DocumentTypeID = soh_Outer.SaleContractTypeID AND SET_DocumentApprove.DocumentNo = soh_Outer.ContractNo AND SET_DocumentApprove.CreateDate = ( SELECT MAX(CreateDate) FROM SET_DocumentApprove WHERE CompanyID = soh_Outer.CompanyID AND PeriodID = soh_Outer.PeriodID AND DocumentTypeID = soh_Outer.SaleContractTypeID AND DocumentNo = soh_Outer.ContractNo ) inner join Set_documentPendingApprove on Set_documentPendingApprove.DocumentApproveID = SET_DocumentApprove.DocumentApproveID and Set_documentPendingApprove.companyID = SET_DocumentApprove.companyID and Set_documentPendingApprove.PeriodID = SET_DocumentApprove.PeriodID
inner join SET_Documenttype on SET_Documenttype.DocumentTypeID = soh_Outer.SaleContractTypeID and SET_Documenttype.CompanyID = soh_Outer.CompanyID and SET_Documenttype.periodId = soh_Outer.periodId
INNER JOIN SET_UserApprovalAmount ON SET_UserApprovalAmount.CompanyID = soh_Outer.CompanyID AND SET_UserApprovalAmount.PeriodID = soh_Outer.PeriodID AND SET_UserApprovalAmount.Status = 1 AND (SET_UserApprovalAmount.DocumentTypeID = soh_Outer.SaleContractTypeID OR SET_UserApprovalAmount.DocumentTypeID IS NULL) AND (1 = (CASE WHEN SET_UserApprovalAmount.EffectiveDateTo IS NULL AND CAST(CONVERT(VARCHAR(10), GETDATE(), 110) AS DATETIME) >= SET_UserApprovalAmount.EffectiveDateFrom THEN 1 WHEN SET_UserApprovalAmount.EffectiveDateTo IS NOT NULL AND CAST(CONVERT(VARCHAR(10), GETDATE(), 110) AS DATETIME) BETWEEN SET_UserApprovalAmount.EffectiveDateFrom AND SET_UserApprovalAmount.EffectiveDateTo THEN 1 ELSE 0 END)) AND (1 = (CASE WHEN SET_UserApprovalAmount.AmountTo IS NULL AND ( SELECT soh.TotalAmount FROM SAL_ContractHeader soh WHERE soh.CompanyID = soh_Outer.CompanyID AND soh.PeriodID = soh_Outer.PeriodID AND soh.ContractID = soh_Outer.ContractID ) >= SET_UserApprovalAmount.AmountFrom THEN 1 WHEN SET_UserApprovalAmount.AmountTo IS NOT NULL AND ( SELECT soh.TotalAmount FROM SAL_ContractHeader soh WHERE soh.CompanyID = soh_Outer.CompanyID AND soh.PeriodID = soh_Outer.PeriodID AND soh.ContractID = soh_Outer.ContractID ) BETWEEN SET_UserApprovalAmount.AmountFrom AND SET_UserApprovalAmount.AmountTo THEN 1 ELSE 0 END))
AND (SET_UserApprovalAmount.ApprovalItemGroup = INV_Item.ApprovalItemGroupID OR SET_UserApprovalAmount.ApprovalItemGroup IS NULL) left join UsersInRoles on UsersInRoles.RoleId = SET_UserApprovalAmount.RoleId and UsersInRoles.CompanyID = SET_UserApprovalAmount.CompanyID
inner join Set_PeriodCustom on soh_Outer.ContractDate between Set_PeriodCustom.StartDate and Set_PeriodCustom.EndDate and Set_PeriodCustom.Status = 1 and SET_PeriodCustom.FiscalID = @CurrentFiscalID
--group by soh_Outer.ContractID, soh_Outer.CompanyID, soh_Outer.PeriodID, soh_Outer.SaleContractTypeID, soh_Outer.CustomerID, soh_Outer.BrokerID, -- soh_Outer.PaymentTermID, soh_Outer.Season, soh_Outer.ContractNo, soh_Outer.ContractDate, soh_Outer.PaymentDate, soh_Outer.DispatchDate, soh_Outer.DTRENo, -- soh_Outer.DTREDate, soh_Outer.IsApproved, soh_Outer.ApprovedBy, soh_Outer.ApprovalDate, soh_Outer.Remarks, soh_Outer.IsPaid, soh_Outer.PaidAmount, -- soh_Outer.StatusCode, soh_Outer.Status, soh_Outer.CreatedBy, soh_Outer.CreateDate, soh_Outer.UpdatedBy, soh_Outer.UpdateDate, soh_Outer.CreatedByValue, -- soh_Outer.UpdatedByValue, AR_SET_Customer.CustomerName, tbl_Broker.CustomerName, SET_DocumentApprove.ApprovalStatus, -- Set_documentPendingApprove.ApprovalOperator -- ,SET_Documenttype.DocumentType,SET_PeriodCustom.PeriodSetName -- ,Set_documentPendingApprove.ApprovalUserID
) AS SAL_ContractHeader {AdditionalParameters}
